---@field Cell                          	UnityEngine.RectTransform               	@ 3    
local SalaryPlanPopup = Class("SalaryPlanPopup")

function SalaryPlanPopup:__init()
    self.configs = nil
    self.delta = 1
    self.config = nil
end

function SalaryPlanPopup:__delete()
    self.delta = 1
    self.configs = nil
    self.controller = nil
    self.config = nil
end

function SalaryPlanPopup:Awake()
    self.LevelList = CfUtils.GetOrAddComponent(self.LevelList, typeof(LoopListView2))
    SetButtonAction(self.BtnClose, function()
        CfUtils.DialogBack()
    end)
    self.configs = {}
    ---@type TableML.TableFile
    local tableFile = CfUtils.GetCfTable(AutoIds.IdSetting6511)
    for i, row in pairs(tableFile) do
        local id = checkNumber(row:Get("id"))
        local name = parse_localizeText(row, "name")
        local point = checkNumber(row:Get("point"))
        local num = checkNumber(row:Get("rewardNum"))
        table.insert(self.configs, {
            id = id,
            name = name,
            point = point,
            num = num
        })
        --local go = KTool.Instantiate(contentTrans.gameObject, self.Cell.gameObject, true)
        --CfUtils.SetActive(go, true)
        --CfUtils.SetUISwitchImage(go.transform:Find("Imgbg"), (i - 1) % 4 + 1)
        --CfUtils.FillText(go.transform:Find("txttitle"), name)
        --CfUtils.FillText(go.transform:Find("txtnumup"), point)
    end
end

function SalaryPlanPopup:FreshListView()
    if not self.LevelList.IsListViewInit then
        self.LevelList:InitListView(#self.configs, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LevelList, #self.configs)
    end
end

function SalaryPlanPopup:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("Cell")
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        -- 这里一个cell是一个页面，一个页面有9个按钮
    end
    local data = self.configs[index + 1]
    if isNotNull(data) then
        CfUtils.SetUISwitchImage(cell.transform:Find("imgbg"), checkNumber(data.id) == checkNumber(self.config.id) and 3 or 2)
        CfUtils.SetActive(cell.transform:Find("imgicon"),checkNumber(data.id) == checkNumber(self.config.id))
        CfUtils.FillText(cell.transform:Find("txttitle"), data.name)
        CfUtils.FillText(cell.transform:Find("txtnumday"), data.num)
        CfUtils.FillText(cell.transform:Find("txtnummonth"), checkNumber(data.num) * checkNumber(self.delta))
        CfUtils.FillText(cell.transform:Find("txtnumup"), data.point)
    end
    return cell
end

function SalaryPlanPopup:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:FreshListView()
        local index = 0
        for i, v in pairs(self.configs) do
            if checkNumber(v.id) == checkNumber(self.config.id) then
                index = i
                break
            end
        end
        if index > 6 then
            self.LevelList:MovePanelToItemIndex(index)
        end
    end))
    return coWait
end

function SalaryPlanPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.delta = checkNumber(self.controller.Argument.parameters.delta)
        self.config = checkTable(self.controller.Argument.parameters.config)
    end))
    return coWait
end

function SalaryPlanPopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return SalaryPlanPopup